CREATE OR REPLACE FUNCTION public.update_shirt_campaign_with_optional_lot(p_campaign_id UUID, p_name TEXT, p_default_sale_price NUMERIC, p_supplier TEXT DEFAULT NULL, p_additional_quantity INTEGER DEFAULT 0, p_additional_unit_cost NUMERIC DEFAULT 0, p_purchase_date DATE DEFAULT CURRENT_DATE, p_notes TEXT DEFAULT NULL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_user_id UUID := auth.uid(); v_campaign public.shirt_campaigns%ROWTYPE; v_lot_id UUID := NULL; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuario nao autenticado'; END IF; IF p_name IS NULL OR TRIM(p_name) = '' THEN RAISE EXCEPTION 'Informe o nome da campanha'; END IF; IF p_default_sale_price IS NULL OR p_default_sale_price < 0 THEN RAISE EXCEPTION 'O preco de venda nao pode ser negativo'; END IF; SELECT * INTO v_campaign FROM public.shirt_campaigns WHERE id = p_campaign_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campanha nao encontrada'; END IF; IF NOT (has_role(v_user_id, 'admin'::app_role) OR (has_role(v_user_id, 'diretoria'::app_role) AND v_campaign.society_id = get_user_society_id(v_user_id))) THEN RAISE EXCEPTION 'Usuario sem permissao para esta campanha'; END IF; UPDATE public.shirt_campaigns SET name = TRIM(p_name), default_sale_price = p_default_sale_price, supplier = NULLIF(TRIM(COALESCE(p_supplier, '')), ''), updated_at = now() WHERE id = p_campaign_id; IF p_additional_quantity IS NOT NULL AND p_additional_quantity > 0 THEN v_lot_id := public.add_shirt_campaign_lot(p_campaign_id, p_additional_quantity, COALESCE(p_additional_unit_cost, 0), p_supplier, p_purchase_date, p_notes); END IF; RETURN v_lot_id; END; $function$;